1	"use client";
2	
3	import { useMemo, useState } from "react";
4	import Link from "next/link";
5	import { StatusDot, Badge, EmptyState } from "@/components/ui/primitives";
6	
7	export type ServerRow = {
8	  id: string;
9	  hostname: string;
10	  status: string;
11	  isFree: boolean;
12	  planLine: string;
13	  osName: string;
14	  project: { name: string; color: string } | null;
15	  endpoint: string | null;
16	  created: string;
17	};
18	
19	export function ServersList({ servers }: { servers: ServerRow[] }) {
20	  const [filter, setFilter] = useState<string>("ALL");
21	
22	  const statuses = useMemo(() => {
23	    const set = new Map<string, number>();
24	    for (const s of servers) set.set(s.status, (set.get(s.status) ?? 0) + 1);
25	    return Array.from(set.entries());
26	  }, [servers]);
27	
28	  const visible = filter === "ALL" ? servers : servers.filter((s) => s.status === filter);
29	
30	  return (
31	    <div className="space-y-4">
32	      <div className="flex flex-wrap gap-2">
33	        <button
34	          type="button"
35	          onClick={() => setFilter("ALL")}
36	          className={`rounded-full border px-3.5 py-1.5 text-xs font-medium transition-colors ${
37	            filter === "ALL"
38	              ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
39	              : "border-white/10 bg-white/[0.03] text-slate-400 hover:border-white/20 hover:text-white"
40	          }`}
41	        >
42	          All · {servers.length}
43	        </button>
44	        {statuses.map(([status, count]) => (
45	          <button
46	            key={status}
47	            type="button"
48	            onClick={() => setFilter(filter === status ? "ALL" : status)}
49	            className={`rounded-full border px-3.5 py-1.5 text-xs font-medium transition-colors ${
50	              filter === status
51	                ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
52	                : "border-white/10 bg-white/[0.03] text-slate-400 hover:border-white/20 hover:text-white"
53	            }`}
54	          >
55	            {status.toLowerCase().replace(/_/g, " ")} · {count}
56	          </button>
57	        ))}
58	      </div>
59	
60	      {visible.length === 0 ? (
61	        <EmptyState
62	          title="Nothing matches this filter"
63	          sub="No servers are currently in this state."
64	          action={
65	            <button className="btn-secondary" onClick={() => setFilter("ALL")}>
66	              Show all servers
67	            </button>
68	          }
69	        />
70	      ) : (
71	        <div className="card overflow-x-auto p-0">
72	          <table className="table-shell min-w-[760px]">
73	            <thead>
74	              <tr>
75	                <th>Status</th>
76	                <th>Hostname</th>
77	                <th>Project</th>
78	                <th>Specs</th>
79	                <th>Access</th>
80	                <th>Created</th>
81	                <th className="text-right">Actions</th>
82	              </tr>
83	            </thead>
84	            <tbody>
85	              {visible.map((s) => (
86	                <tr key={s.id}>
87	                  <td>
88	                    <StatusDot status={s.status} />
89	                  </td>
90	                  <td>
91	                    <Link
92	                      href={`/dashboard/servers/${s.id}`}
93	                      className="font-semibold text-slate-100 hover:text-brand-300"
94	                    >
95	                      {s.hostname}
96	                    </Link>
97	                    {s.isFree && (
98	                      <span className="ml-2 align-middle">
99	                        <Badge tone="brand">free</Badge>
100	                      </span>
101	                    )}
102	                    <p className="text-xs text-slate-500">{s.osName}</p>
103	                  </td>
104	                  <td>
105	                    {s.project ? (
106	                      <span className="inline-flex items-center gap-2 text-xs text-slate-300">
107	                        <span
108	                          className="h-2.5 w-2.5 rounded-full"
109	                          style={{ background: s.project.color }}
110	                        />
111	                        {s.project.name}
112	                      </span>
113	                    ) : (
114	                      <span className="text-xs text-slate-600">—</span>
115	                    )}
116	                  </td>
117	                  <td className="text-slate-400">{s.planLine}</td>
118	                  <td className="font-mono text-xs text-slate-400">{s.endpoint ?? "—"}</td>
119	                  <td className="text-slate-400">{s.created}</td>
120	                  <td className="text-right">
121	                    <Link href={`/dashboard/servers/${s.id}`} className="btn-secondary px-3 py-1 text-xs">
122	                      Manage
123	                    </Link>
124	                  </td>
125	                </tr>
126	              ))}
127	            </tbody>
128	          </table>
129	        </div>
130	      )}
131	    </div>
132	  );
133	}
