1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { registrarConfigured, transfersAvailable, getDnsHosts } from "@/lib/registrar";
5	import { PageHeader, StatCard, Badge, StatusDot, EmptyState, fmtMoney } from "@/components/ui/primitives";
6	import { DomainSearch } from "@/components/customer/DomainSearch";
7	import { DomainAutoRenewToggle } from "@/components/customer/DomainControls";
8	
9	export const dynamic = "force-dynamic";
10	
11	function daysUntil(d: Date): number {
12	  return Math.ceil((d.getTime() - Date.now()) / 86_400_000);
13	}
14	
15	function expiryTone(days: number | null): "green" | "amber" | "red" | "slate" {
16	  if (days === null) return "slate";
17	  if (days < 0) return "red";
18	  if (days <= 30) return "amber";
19	  return "green";
20	}
21	
22	function expiryLabel(d: Date | null): string {
23	  if (!d) return "—";
24	  const days = daysUntil(d);
25	  if (days < 0) return `expired ${-days}d ago`;
26	  if (days === 0) return "expires today";
27	  return `in ${days} day${days === 1 ? "" : "s"}`;
28	}
29	
30	const statusDotFor = (s: string) =>
31	  s === "ACTIVE"
32	    ? "RUNNING"
33	    : s === "PENDING" || s === "TRANSFER_PENDING"
34	      ? "PENDING"
35	      : s === "EXPIRED"
36	        ? "SUSPENDED"
37	        : "ERROR";
38	
39	export default async function DomainsPage() {
40	  const user = await requireUser();
41	  const configured = registrarConfigured();
42	  const canTransfer = transfersAvailable();
43	  const domains = await db.domain.findMany({
44	    where: { userId: user.id },
45	    orderBy: { createdAt: "desc" },
46	  });
47	
48	  // DNS record counts for active domains (best-effort — registrar may be briefly unavailable).
49	  const recordCounts = new Map<string, number | null>();
50	  if (configured) {
51	    await Promise.all(
52	      domains
53	        .filter((d) => d.status === "ACTIVE")
54	        .map(async (d) => {
55	          try {
56	            const hosts = await getDnsHosts(d.name);
57	            recordCounts.set(d.id, hosts.length);
58	          } catch {
59	            recordCounts.set(d.id, null);
60	          }
61	        })
62	    );
63	  }
64	
65	  const active = domains.filter((d) => d.status === "ACTIVE").length;
66	  const expiringSoon = domains.filter(
67	    (d) => d.status === "ACTIVE" && d.expiresAt && daysUntil(d.expiresAt) <= 30 && daysUntil(d.expiresAt) >= 0
68	  ).length;
69	
70	  return (
71	    <div className="space-y-6">
72	      <PageHeader title="Domains" sub="Register, transfer in and manage domains, right next to your servers.">
73	        {canTransfer && (
74	          <Link href="/dashboard/domains/transfer" className="btn-secondary">
75	            Transfer a domain in
76	          </Link>
77	        )}
78	        {configured && (
79	          <Link href="/dashboard/domains/register" className="btn-primary">
80	            Register a domain
81	          </Link>
82	        )}
83	      </PageHeader>
84	
85	      <DomainSearch configured={configured} />
86	
87	      {domains.length > 0 && (
88	        <div className="grid gap-4 sm:grid-cols-3">
89	          <StatCard
90	            label="Domains"
91	            value={String(domains.length)}
92	            icon={
93	              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
94	                <circle cx="12" cy="12" r="9" />
95	                <path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18" />
96	              </svg>
97	            }
98	          />
99	          <StatCard
100	            label="Active"
101	            value={String(active)}
102	            delta={active === domains.length ? "all active" : `${domains.length - active} inactive`}
103	            deltaGood={active === domains.length}
104	          />
105	          <StatCard
106	            label="Expiring soon"
107	            value={String(expiringSoon)}
108	            delta={expiringSoon === 0 ? "nothing due" : "within 30 days"}
109	            deltaGood={expiringSoon === 0}
110	          />
111	        </div>
112	      )}
113	
114	      {domains.length === 0 ? (
115	        <EmptyState
116	          title="No domains yet"
117	          sub={
118	            configured
119	              ? "Search above for an available name — you can register and point it at any of your servers in minutes."
120	              : "Domain registration lights up once the registrar integration is configured. Your registered domains will appear here."
121	          }
122	          action={
123	            configured || canTransfer ? (
124	              <div className="flex flex-wrap items-center justify-center gap-3">
125	                {configured && (
126	                  <Link href="/dashboard/domains/register" className="btn-primary">
127	                    Register your first domain
128	                  </Link>
129	                )}
130	                {canTransfer && (
131	                  <Link href="/dashboard/domains/transfer" className="btn-secondary">
132	                    Already own one? Transfer it in
133	                  </Link>
134	                )}
135	              </div>
136	            ) : undefined
137	          }
138	        />
139	      ) : (
140	        <div className="card p-0">
141	          <div className="flex items-center justify-between px-5 pt-5">
142	            <p className="section-label">Your domains</p>
143	            <span className="text-xs text-slate-500">{domains.length} total</span>
144	          </div>
145	
146	          {/* Card grid on small screens, table on large */}
147	          <div className="grid gap-3 p-5 lg:hidden">
148	            {domains.map((d) => {
149	              const days = d.expiresAt ? daysUntil(d.expiresAt) : null;
150	              const count = recordCounts.get(d.id);
151	              return (
152	                <Link
153	                  key={d.id}
154	                  href={`/dashboard/domains/${d.id}`}
155	                  className="card card-hover block p-4"
156	                >
157	                  <div className="flex items-center justify-between gap-2">
158	                    <span className="truncate font-mono text-sm font-semibold text-slate-100">{d.name}</span>
159	                    <StatusDot status={statusDotFor(d.status)} label={d.status} />
160	                  </div>
161	                  {d.status === "TRANSFER_PENDING" && (
162	                    <p className="mt-2 text-xs text-amber-300">
163	                      Transfer in progress — approve the confirmation email from your old registrar. Usually
164	                      5–7 days.
165	                    </p>
166	                  )}
167	                  {d.status === "TRANSFER_FAILED" && (
168	                    <p className="mt-2 text-xs text-red-300">
169	                      Transfer didn&apos;t complete — you were credited back. Tap to see why.
170	                    </p>
171	                  )}
172	                  <div className="mt-3 flex flex-wrap items-center gap-2 text-xs">
173	                    {d.status === "TRANSFER_PENDING" ? (
174	                      <Badge tone="amber">transfer in</Badge>
175	                    ) : (
176	                      <Badge tone={expiryTone(days)}>{expiryLabel(d.expiresAt)}</Badge>
177	                    )}
178	                    <Badge tone={d.autoRenew ? "green" : "slate"}>
179	                      auto-renew {d.autoRenew ? "on" : "off"}
180	                    </Badge>
181	                    {d.status === "ACTIVE" && (
182	                      <Badge tone="slate">{count === null || count === undefined ? "DNS —" : `${count} DNS`}</Badge>
183	                    )}
184	                    <span className="ml-auto text-slate-400">{fmtMoney(d.priceCents)}/yr</span>
185	                  </div>
186	                </Link>
187	              );
188	            })}
189	          </div>
190	
191	          <div className="hidden overflow-x-auto lg:block">
192	            <table className="table-shell mt-2 min-w-[760px]">
193	              <thead>
194	                <tr>
195	                  <th>Domain</th>
196	                  <th>Status</th>
197	                  <th>Expires</th>
198	                  <th>DNS</th>
199	                  <th>Price</th>
200	                  <th>Auto-renew</th>
201	                  <th className="text-right">Actions</th>
202	                </tr>
203	              </thead>
204	              <tbody>
205	                {domains.map((d) => {
206	                  const days = d.expiresAt ? daysUntil(d.expiresAt) : null;
207	                  const count = recordCounts.get(d.id);
208	                  return (
209	                    <tr key={d.id}>
210	                      <td>
211	                        <Link
212	                          href={`/dashboard/domains/${d.id}`}
213	                          className="font-mono text-sm font-semibold text-slate-100 hover:text-brand-300"
214	                        >
215	                          {d.name}
216	                        </Link>
217	                      </td>
218	                      <td>
219	                        <StatusDot status={statusDotFor(d.status)} label={d.status} />
220	                      </td>
221	                      <td>
222	                        {d.status === "TRANSFER_PENDING" ? (
223	                          <div className="flex flex-col">
224	                            <span className="text-sm text-amber-300">transferring in</span>
225	                            <span className="text-xs text-slate-500">approve the registrar email · 5–7 days</span>
226	                          </div>
227	                        ) : d.expiresAt ? (
228	                          <div className="flex flex-col">
229	                            <span className="text-sm text-slate-300">
230	                              {d.expiresAt.toISOString().slice(0, 10)}
231	                            </span>
232	                            <span className={`text-xs ${expiryTone(days) === "amber" ? "text-amber-400" : expiryTone(days) === "red" ? "text-red-400" : "text-slate-500"}`}>
233	                              {expiryLabel(d.expiresAt)}
234	                            </span>
235	                          </div>
236	                        ) : (
237	                          <span className="text-slate-500">—</span>
238	                        )}
239	                      </td>
240	                      <td className="text-slate-400">
241	                        {d.status !== "ACTIVE"
242	                          ? "—"
243	                          : count === null || count === undefined
244	                            ? "—"
245	                            : `${count} record${count === 1 ? "" : "s"}`}
246	                      </td>
247	                      <td className="text-slate-400">{fmtMoney(d.priceCents)}/yr</td>
248	                      <td>
249	                        <DomainAutoRenewToggle domainId={d.id} autoRenew={d.autoRenew} />
250	                      </td>
251	                      <td className="text-right">
252	                        <Link href={`/dashboard/domains/${d.id}`} className="btn-secondary px-3 py-1 text-xs">
253	                          Manage
254	                        </Link>
255	                      </td>
256	                    </tr>
257	                  );
258	                })}
259	              </tbody>
260	            </table>
261	          </div>
262	        </div>
263	      )}
264	    </div>
265	  );
266	}
