1	import type { InvoiceStatus } from "@prisma/client";
2	import { Badge } from "@/components/ui/primitives";
3	
4	const TONE: Record<InvoiceStatus, "brand" | "green" | "red" | "amber" | "slate"> = {
5	  OPEN: "amber",
6	  PAID: "green",
7	  VOID: "slate",
8	  REFUNDED: "brand",
9	};
10	
11	const LABEL: Record<InvoiceStatus, string> = {
12	  OPEN: "Open",
13	  PAID: "Paid",
14	  VOID: "Void",
15	  REFUNDED: "Refunded",
16	};
17	
18	export function InvoiceStatusBadge({ status }: { status: InvoiceStatus }) {
19	  return <Badge tone={TONE[status] ?? "slate"}>{LABEL[status] ?? status}</Badge>;
20	}
21	
22	/** Anchor (not Link) — the target is a raw HTML document served by the API route. */
