24	  id,
25	  className = "btn-secondary py-1.5",
26	  label = "Download / Print",
27	}: {
28	  id: string;
29	  className?: string;
30	  label?: string;
31	}) {
32	  return (
33	    <a href={`/api/invoices/${id}`} target="_blank" rel="noopener noreferrer" className={className}>
34	      {label}
35	    </a>
36	  );
37	}
